20	import * as zrUtil from 'zrender/src/core/util';
21	import ChartView from '../../view/Chart';
22	import * as graphic from '../../util/graphic';
23	import { setStatesStylesFromModel, toggleHoverEmphasis } from '../../util/states';
24	import Path, { PathProps } from 'zrender/src/graphic/Path';
25	import BoxplotSeriesModel, { BoxplotDataItemOption } from './BoxplotSeries';
26	import GlobalModel from '../../model/Global';
27	import ExtensionAPI from '../../core/ExtensionAPI';
