32	class BoxplotView extends ChartView {
33	    static type = 'boxplot';
34	    type = BoxplotView.type;
35	
36	    private _data: SeriesData;
37	
38	    render(seriesModel: BoxplotSeriesModel, ecModel: GlobalModel, api: ExtensionAPI) {
39	        const data = seriesModel.getData();
40	        const group = this.group;
41	        const oldData = this._data;
42	
43	        // There is no old data only when first rendering or switching from
44	        // stream mode to normal mode, where previous elements should be removed.
45	        if (!this._data) {
46	            group.removeAll();
47	        }
48	
49	        const constDim = seriesModel.get('layout') === 'horizontal' ? 1 : 0;
50	
51	        data.diff(oldData)
52	            .add(function (newIdx) {
53	                if (data.hasValue(newIdx)) {
54	                    const itemLayout = data.getItemLayout(newIdx) as BoxplotItemLayout;
55	                    const symbolEl = createNormalBox(itemLayout, data, newIdx, constDim, true);
56	                    data.setItemGraphicEl(newIdx, symbolEl);
57	                    group.add(symbolEl);
58	                }
59	            })
60	            .update(function (newIdx, oldIdx) {
61	                let symbolEl = oldData.getItemGraphicEl(oldIdx) as BoxPath;
62	
63	                // Empty data
64	                if (!data.hasValue(newIdx)) {
65	                    group.remove(symbolEl);
66	                    return;
67	                }
68	
69	                const itemLayout = data.getItemLayout(newIdx) as BoxplotItemLayout;
70	                if (!symbolEl) {
71	                    symbolEl = createNormalBox(itemLayout, data, newIdx, constDim);
72	                }
73	                else {
74	                    saveOldStyle(symbolEl);
75	                    updateNormalBoxData(itemLayout, symbolEl, data, newIdx);
76	                }
77	
78	                group.add(symbolEl);
79	
80	                data.setItemGraphicEl(newIdx, symbolEl);
81	            })
82	            .remove(function (oldIdx) {
83	                const el = oldData.getItemGraphicEl(oldIdx);
84	                el && group.remove(el);
85	            })
86	            .execute();
87	
88	        this._data = data;
89	    }
90	
91	    remove(ecModel: GlobalModel) {
92	        const group = this.group;
93	        const data = this._data;
94	        this._data = null;
95	        data && data.eachItemGraphicEl(function (el) {
96	            el && group.remove(el);
97	        });
98	    }
99	}
