101	class BoxPathShape {
102	    points: number[][];
103	}
104	
105	interface BoxPathProps extends PathProps {
106	    shape?: Partial<BoxPathShape>
107	}
108	
109	class BoxPath extends Path<BoxPathProps> {
110	
111	    readonly type = 'boxplotBoxPath';
112	    shape: BoxPathShape;
113	
114	    constructor(opts?: BoxPathProps) {
115	        super(opts);
116	    }
117	
118	    getDefaultShape() {
119	        return new BoxPathShape();
120	    }
121	
122	    buildPath(ctx: CanvasRenderingContext2D, shape: BoxPathShape) {
123	        const ends = shape.points;
124	
125	        let i = 0;
126	        ctx.moveTo(ends[i][0], ends[i][1]);
127	        i++;
128	        for (; i < 4; i++) {
129	            ctx.lineTo(ends[i][0], ends[i][1]);
130	        }
131	        ctx.closePath();
132	
133	        for (; i < ends.length; i++) {
134	            ctx.moveTo(ends[i][0], ends[i][1]);
135	            i++;
136	            ctx.lineTo(ends[i][0], ends[i][1]);
137	        }
138	    }
139	
140	}
141	
142	function createNormalBox(
143	    itemLayout: BoxplotItemLayout,
144	    data: SeriesData,
145	    dataIndex: number,
146	    constDim: number,
147	    isInit?: boolean
148	) {
149	    const ends = itemLayout.ends;
150	
151	    const el = new BoxPath({
152	        shape: {
153	            points: isInit
154	                ? transInit(ends, constDim, itemLayout)
155	                : ends
156	        }
157	    });
158	
159	    updateNormalBoxData(itemLayout, el, data, dataIndex, isInit);
160	
161	    return el;
162	}
163	
164	function updateNormalBoxData(
165	    itemLayout: BoxplotItemLayout,
166	    el: BoxPath,
167	    data: SeriesData,
168	    dataIndex: number,
169	    isInit?: boolean
170	) {
171	    const seriesModel = data.hostModel;
172	    const updateMethod = graphic[isInit ? 'initProps' : 'updateProps'];
173	
174	    updateMethod(
175	        el,
176	        {shape: {points: itemLayout.ends}},
177	        seriesModel,
178	        dataIndex
179	    );
180	
181	    el.useStyle(data.getItemVisual(dataIndex, 'style'));
182	    el.style.strokeNoScale = true;
183	
184	    el.z2 = 100;
185	
186	    const itemModel = data.getItemModel<BoxplotDataItemOption>(dataIndex);
187	    const emphasisModel = itemModel.getModel('emphasis');
188	
189	    setStatesStylesFromModel(el, itemModel);
190	
191	    toggleHoverEmphasis(el, emphasisModel.get('focus'), emphasisModel.get('blurScope'), emphasisModel.get('disabled'));
192	}
193	
194	function transInit(points: number[][], dim: number, itemLayout: BoxplotItemLayout) {
195	    return zrUtil.map(points, function (point) {
196	        point = point.slice();
197	        point[dim] = itemLayout.initBaseline;
198	        return point;
199	    });
200	}
201	
202	export default BoxplotView;

