20	import * as zrUtil from 'zrender/src/core/util';
21	import {parsePercent} from '../../util/number';
22	import type GlobalModel from '../../model/Global';
23	import BoxplotSeriesModel from './BoxplotSeries';
24	import Axis2D from '../../coord/cartesian/Axis2D';
25	
26	const each = zrUtil.each;
27	
28	interface GroupItem {
29	    seriesModels: BoxplotSeriesModel[]
30	    axis: Axis2D
31	    boxOffsetList: number[]
32	    boxWidthList: number[]
33	}
34	
35	export interface BoxplotItemLayout {
36	    ends: number[][]
37	    initBaseline: number
38	}
39	
40	export default function boxplotLayout(ecModel: GlobalModel) {
41	
42	    const groupResult = groupSeriesByAxis(ecModel);
43	
44	    each(groupResult, function (groupItem) {
45	        const seriesModels = groupItem.seriesModels;
46	
47	        if (!seriesModels.length) {
48	            return;
49	        }
50	
51	        calculateBase(groupItem);
52	
53	        each(seriesModels, function (seriesModel, idx) {
54	            layoutSingleSeries(
55	                seriesModel,
56	                groupItem.boxOffsetList[idx],
57	                groupItem.boxWidthList[idx]
58	            );
59	        });
60	    });
61	}
62	
63	/**
64	 * Group series by axis.
65	 */
66	function groupSeriesByAxis(ecModel: GlobalModel) {
67	    const result: GroupItem[] = [];
68	    const axisList: Axis2D[] = [];
69	
70	    ecModel.eachSeriesByType('boxplot', function (seriesModel: BoxplotSeriesModel) {
71	        const baseAxis = seriesModel.getBaseAxis();
72	        let idx = zrUtil.indexOf(axisList, baseAxis);
73	
74	        if (idx < 0) {
75	            idx = axisList.length;
76	            axisList[idx] = baseAxis;
77	            result[idx] = {
78	                axis: baseAxis,
79	                seriesModels: []
80	            } as GroupItem;
81	        }
82	
83	        result[idx].seriesModels.push(seriesModel);
84	    });
85	
86	    return result;
87	}
88	
89	/**
90	 * Calculate offset and box width for each series.
91	 */
92	function calculateBase(groupItem: GroupItem) {
93	    const baseAxis = groupItem.axis;
94	    const seriesModels = groupItem.seriesModels;
95	    const seriesCount = seriesModels.length;
96	
97	    const boxWidthList: number[] = groupItem.boxWidthList = [];
98	    const boxOffsetList: number[] = groupItem.boxOffsetList = [];
99	    const boundList: number[][] = [];
100	
101	    let bandWidth: number;
102	    if (baseAxis.type === 'category') {
103	        bandWidth = baseAxis.getBandWidth();
104	    }
105	    else {
106	        let maxDataCount = 0;
107	        each(seriesModels, function (seriesModel) {
108	            maxDataCount = Math.max(maxDataCount, seriesModel.getData().count());
109	        });
110	        const extent = baseAxis.getExtent();
111	        bandWidth = Math.abs(extent[1] - extent[0]) / maxDataCount;
112	    }
113	
114	    each(seriesModels, function (seriesModel) {
115	        let boxWidthBound = seriesModel.get('boxWidth');
116	        if (!zrUtil.isArray(boxWidthBound)) {
117	            boxWidthBound = [boxWidthBound, boxWidthBound];
118	        }
119	        boundList.push([
120	            parsePercent(boxWidthBound[0], bandWidth) || 0,
121	            parsePercent(boxWidthBound[1], bandWidth) || 0
122	        ]);
123	    });
124	
125	    const availableWidth = bandWidth * 0.8 - 2;
126	    const boxGap = availableWidth / seriesCount * 0.3;
127	    const boxWidth = (availableWidth - boxGap * (seriesCount - 1)) / seriesCount;
128	    let base = boxWidth / 2 - availableWidth / 2;
129	
130	    each(seriesModels, function (seriesModel, idx) {
131	        boxOffsetList.push(base);
132	        base += boxGap + boxWidth;
133	
134	        boxWidthList.push(
135	            Math.min(Math.max(boxWidth, boundList[idx][0]), boundList[idx][1])
136	        );
137	    });
138	}
139	
140	/**
141	 * Calculate points location for each series.
142	 */
143	function layoutSingleSeries(seriesModel: BoxplotSeriesModel, offset: number, boxWidth: number) {
144	    const coordSys = seriesModel.coordinateSystem;
145	    const data = seriesModel.getData();
146	    const halfWidth = boxWidth / 2;
147	    const cDimIdx = seriesModel.get('layout') === 'horizontal' ? 0 : 1;
148	    const vDimIdx = 1 - cDimIdx;
149	    const coordDims = ['x', 'y'];
150	    const cDim = data.mapDimension(coordDims[cDimIdx]);
151	    const vDims = data.mapDimensionsAll(coordDims[vDimIdx]);
152	
153	    if (cDim == null || vDims.length < 5) {
154	        return;
155	    }
156	
157	    for (let dataIndex = 0; dataIndex < data.count(); dataIndex++) {
158	        const axisDimVal = data.get(cDim, dataIndex) as number;
159	
160	        const median = getPoint(axisDimVal, vDims[2], dataIndex);
161	        const end1 = getPoint(axisDimVal, vDims[0], dataIndex);
162	        const end2 = getPoint(axisDimVal, vDims[1], dataIndex);
163	        const end4 = getPoint(axisDimVal, vDims[3], dataIndex);
164	        const end5 = getPoint(axisDimVal, vDims[4], dataIndex);
165	
166	        const ends: number[][] = [];
167	        addBodyEnd(ends, end2, false);
168	        addBodyEnd(ends, end4, true);
169	
170	        ends.push(end1, end2, end5, end4);
171	        layEndLine(ends, end1);
172	        layEndLine(ends, end5);
173	        layEndLine(ends, median);
174	
175	        data.setItemLayout(dataIndex, {
176	            initBaseline: median[vDimIdx],
177	            ends: ends
178	        } as BoxplotItemLayout);
179	    }
180	
181	    function getPoint(axisDimVal: number, dim: string, dataIndex: number) {
182	        const val = data.get(dim, dataIndex) as number;
183	        const p = [];
184	        p[cDimIdx] = axisDimVal;
185	        p[vDimIdx] = val;
186	        let point;
187	        if (isNaN(axisDimVal) || isNaN(val)) {
188	            point = [NaN, NaN];
189	        }
190	        else {
191	            point = coordSys.dataToPoint(p);
192	            point[cDimIdx] += offset;
193	        }
194	        return point;
195	    }
196	
197	    function addBodyEnd(ends: number[][], point: number[], start?: boolean) {
198	        const point1 = point.slice();
199	        const point2 = point.slice();
200	        point1[cDimIdx] += halfWidth;
201	        point2[cDimIdx] -= halfWidth;
202	        start
203	            ? ends.push(point1, point2)
204	            : ends.push(point2, point1);
205	    }
206	
207	    function layEndLine(ends: number[][], endCenter: number[]) {
208	        const from = endCenter.slice();
209	        const to = endCenter.slice();
210	        from[cDimIdx] -= halfWidth;
211	        to[cDimIdx] += halfWidth;
212	        ends.push(from, to);
213	    }
214	}

