20	import { DataTransformOption, ExternalDataTransform } from '../../data/helper/transform';
21	import prepareBoxplotData, { PrepareBoxplotDataOpt } from './prepareBoxplotData';
22	import { throwError, makePrintable } from '../../util/log';
23	import { SOURCE_FORMAT_ARRAY_ROWS } from '../../util/types';
24	
25	
26	export interface BoxplotTransformOption extends DataTransformOption {
27	    type: 'boxplot';
28	    config: PrepareBoxplotDataOpt;
29	}
30	
31	export const boxplotTransform: ExternalDataTransform<BoxplotTransformOption> = {
32	
33	    type: 'echarts:boxplot',
34	
35	    transform: function transform(params) {
36	        const upstream = params.upstream;
37	
38	        if (upstream.sourceFormat !== SOURCE_FORMAT_ARRAY_ROWS) {
39	            let errMsg = '';
40	            if (__DEV__) {
41	                errMsg = makePrintable(
42	                    'source data is not applicable for this boxplot transform. Expect number[][].'
43	                );
44	            }
45	            throwError(errMsg);
46	        }
47	
48	        const result = prepareBoxplotData(
49	            upstream.getRawData() as number[][],
50	            params.config
51	        );
52	
53	        return [{
54	            dimensions: ['ItemName', 'Low', 'Q1', 'Q2', 'Q3', 'High'],
55	            data: result.boxData
56	        }, {
57	            data: result.outliers
58	        }];
59	    }
60	};
