import { createChart, removeChart } from '../test/ut/core/utHelper';

// Safeguard for requirement `boxplot-encode-category-axis`:
// a boxplot backed by data + series.encode on a category axis must use the
// encoded category dimension instead of force-inserting the data index as
// the ordinal value (fixed upstream in PR #20324 / commit 2c6ecb0).
describe('boxplot-encode-category-axis', function () {
    it('honors series.encode on a category axis', function () {
        const chart = createChart();
        chart.setOption({
            xAxis: { type: 'category' },
            yAxis: { type: 'value' },
            series: [{
                type: 'boxplot',
                encode: { x: [5], y: [0, 1, 2, 3, 4] },
                data: [
                    [10, 20, 30, 40, 50, 'one'],
                    [33, 38, 39, 40, 55, 'four'],
                    [40, 45, 50, 52, 66, 'three']
                ]
            }]
        });

        const seriesModel = chart.getModel().getSeriesByIndex(0) as any;
        const data = seriesModel.getData();
        const cDim = data.mapDimension('x');
        const vDims = data.mapDimensionsAll('y');

        // The encoded category names map to ordinal indices 0, 1, 2 in data order.
        expect(data.get(cDim, 0)).toBe(0);
        expect(data.get(cDim, 1)).toBe(1);
        expect(data.get(cDim, 2)).toBe(2);

        // All five value dims are mapped and laid out to finite points.
        expect(vDims.length).toBe(5);
        for (let i = 0; i < data.count(); i++) {
            const layout = data.getItemLayout(i) as any;
            expect(layout.ends.length).toBeGreaterThan(0);
            for (const p of layout.ends) {
                expect(isFinite(p[0])).toBe(true);
                expect(isFinite(p[1])).toBe(true);
            }
        }

        removeChart(chart);
    });

    it('keeps legacy ordinal-index behavior when no encode is given', function () {
        const chart = createChart();
        chart.setOption({
            xAxis: { type: 'category' },
            yAxis: { type: 'value' },
            series: [{
                type: 'boxplot',
                data: [
                    [10, 20, 30, 40, 50],
                    [33, 38, 39, 40, 55],
                    [40, 45, 50, 52, 66]
                ]
            }]
        });

        const seriesModel = chart.getModel().getSeriesByIndex(0) as any;
        const data = seriesModel.getData();
        const cDim = data.mapDimension('x');

        // Without encode, the data index is used as the ordinal value.
        expect(data.get(cDim, 0)).toBe(0);
        expect(data.get(cDim, 1)).toBe(1);
        expect(data.get(cDim, 2)).toBe(2);

        for (let i = 0; i < data.count(); i++) {
            const layout = data.getItemLayout(i) as any;
            for (const p of layout.ends) {
                expect(isFinite(p[0])).toBe(true);
                expect(isFinite(p[1])).toBe(true);
            }
        }

        removeChart(chart);
    });
});

